override fun getApplicableElements(): Collection<String>? = null // Visit all to catch unexpected tags

override fun visitElement(context: XmlContext, element: Element) {
    val tag = element.tagName
    val parentTag = element.parentNode?.nodeName

    // Check unexpected tags
    if (tag != "restrictions" && tag != "restriction") {
        if (parentTag == "restrictions" || parentTag == "restriction") {
            context.report(ISSUE, context.getLocation(element), "Unexpected tag `$tag`")
            return
        }
    }

    if (tag == "restrictions") {
        // Check children
        return
    }

    if (tag != "restriction") return

    // Process restriction
    val keyAttr = element.getAttributeNodeNS(ANDROID_URI, "key")
    val titleAttr = element.getAttributeNodeNS(ANDROID_URI, "title")
    val typeAttr = element.getAttributeNodeNS(ANDROID_URI, "restrictionType")
    val defaultAttr = element.getAttributeNodeNS(ANDROID_URI, "defaultValue")
    val entriesAttr = element.getAttributeNodeNS(ANDROID_URI, "entries")
    val entryValuesAttr = element.getAttributeNodeNS(ANDROID_URI, "entryValues")

    val key = keyAttr?.value ?: ""
    val title = titleAttr?.value ?: ""
    val type = typeAttr?.value ?: ""
    val defaultValue = defaultAttr?.value ?: ""

    // Key checks
    if (key.isEmpty()) {
        context.report(ISSUE, context.getLocation(keyAttr ?: element), "Missing required attribute `android:key`")
    } else {
        if (key.startsWith("@")) {
            context.report(ISSUE, context.getLocation(keyAttr), "Attribute `android:key` cannot be a resource reference")
        }
        if (!seenKeys.add(key)) {
            context.report(ISSUE, context.getLocation(keyAttr), "Duplicate key `$key`")
        }
    }

    // Title checks
    if (title.isEmpty()) {
        // Maybe hidden doesn't need title? I'll report for all except hidden, or just all.
        // The test testMissingRequiredAttributesForHidden expects a warning. So I'll report for all.
        context.report(ISSUE, context.getLocation(titleAttr ?: element), "Missing required attribute `android:title`")
    }

    // Type checks
    if (type.isEmpty()) {
        context.report(ISSUE, context.getLocation(typeAttr ?: element), "Missing required attribute `android:restrictionType`")
        return
    }
    if (type !in VALID_TYPES) {
        context.report(ISSUE, context.getLocation(typeAttr ?: element), "Invalid restriction type `$type`")
        return
    }

    // Type-specific checks
    when (type) {
        "choice", "multi-select" -> {
            if (entriesAttr == null) context.report(ISSUE, context.getLocation(element), "Missing required attribute `android:entries`")
            if (entryValuesAttr == null) context.report(ISSUE, context.getLocation(element), "Missing required attribute `android:entryValues`")
        }
        "bundle", "bundle_array" -> {
            if (defaultAttr != null) {
                context.report(ISSUE, context.getLocation(defaultAttr), "Attribute `android:defaultValue` is not allowed for type `$type`")
            }
        }
        "integer" -> {
            if (defaultValue.isNotEmpty() && defaultValue.toIntOrNull() == null) {
                context.report(ISSUE, context.getLocation(defaultAttr), "Invalid integer value `$defaultValue`")
            }
        }
        "bool" -> {
            if (defaultValue.isNotEmpty() && defaultValue != "true" && defaultValue != "false") {
                context.report(ISSUE, context.getLocation(defaultAttr), "Invalid boolean value `$defaultValue`")
            }
        }
    }

    // Children checks
    if (type == "bundle_array") {
        if (element.hasChildNodes()) {
            // Check if it has element children
            val hasElementChildren = element.childNodes.toList().any { it.nodeType == Node.ELEMENT_NODE }
            if (hasElementChildren) {
                context.report(ISSUE, context.getLocation(element), "Type `bundle_array` cannot have children")
            }
        }
    }

    // Nesting depth
    var depth = 0
    var p: Node? = element.parentNode
    while (p != null) {
        if (p is Element && p.tagName == "restriction") depth++
        p = p.parentNode
    }
    if (depth > 2) { // MAX_NESTING_DEPTH
        context.report(ISSUE, context.getLocation(element), "Nesting depth exceeds maximum of 2")
    }

    // Child count limit
    val childElements = element.childNodes.toList().filter { it.nodeType == Node.ELEMENT_NODE }
    if (childElements.size > 100) {
        context.report(ISSUE, context.getLocation(element), "Too many children (${childElements.size}), max is 100")
    }
}
```

